const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define northern Afghanistan region
  const northAfghan = ee.Geometry.Polygon([
    [[60.5, 35.5], [74.9, 35.5], [74.9, 38.5], [60.5, 38.5], [60.5, 35.5]]
  ]);

  // 2. Load MODIS NDVI collection
  const modisNDVI = ee.ImageCollection('MODIS/006/MOD13Q1')
    .select('NDVI');

  // 3. Baseline period: June-August 2000-2013
  const baseline = modisNDVI
    .filter(ee.Filter.calendarRange(2000, 2013, 'year'))
    .filter(ee.Filter.calendarRange(6, 8, 'month'));

  const baselineSize = baseline.size().getInfo();
  console.log(`Baseline images (2000-2013, Jun-Aug): ${baselineSize}`);

  if (baselineSize === 0) {
    console.log('No baseline data found.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Target period: June-August 2018
  const target = modisNDVI
    .filter(ee.Filter.calendarRange(2018, 2018, 'year'))
    .filter(ee.Filter.calendarRange(6, 8, 'month'));

  const targetSize = target.size().getInfo();
  console.log(`Target images (2018, Jun-Aug): ${targetSize}`);

  if (targetSize === 0) {
    console.log('No 2018 data found.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate mean NDVI (scale factor 0.0001)
  const baselineMean = baseline.mean().multiply(0.0001);
  const targetMean = target.mean().multiply(0.0001);

  // 6. Check pixel counts
  const baselineCount = baselineMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northAfghan,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const targetCount = targetMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northAfghan,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Baseline valid pixels: ${baselineCount}`);
  console.log(`Target valid pixels: ${targetCount}`);

  if (baselineCount === 0 || targetCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Calculate regional mean NDVI
  const baselineNDVI = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northAfghan,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const targetNDVI = targetMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northAfghan,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Baseline NDVI (2000-2013): ${baselineNDVI !== null ? baselineNDVI.toFixed(4) : 'null'}`);
  console.log(`Target NDVI (2018): ${targetNDVI !== null ? targetNDVI.toFixed(4) : 'null'}`);

  // 8. Validation and final answer
  if (baselineNDVI === null || targetNDVI === null || 
      isNaN(baselineNDVI) || isNaN(targetNDVI) ||
      baselineNDVI < -1 || baselineNDVI > 1 ||
      targetNDVI < -1 || targetNDVI > 1) {
    console.log('Invalid NDVI calculation.');
    console.log('<answer>C3</answer>');
    return;
  }

  const change = targetNDVI - baselineNDVI;
  console.log(`NDVI change: ${change.toFixed(4)}`);

  if (targetNDVI < baselineNDVI) {
    console.log('NDVI decreased in 2018.');
    console.log('<answer>A</answer>');
  } else {
    console.log('NDVI did not decrease in 2018.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
